import pyomo.environ as pyo

DATA = {
    "products": ["four_color", "two_color"],
    "resources": ["rollers", "gear_cutting", "polishing"],
    "profit": {"four_color": 24000, "two_color": 10000},
    "usage": {
        "rollers":      {"four_color": 16, "two_color": 8},
        "gear_cutting": {"four_color": 30, "two_color": 12},
        "polishing":    {"four_color": 8,  "two_color": 3},
    },
    "availability": {"rollers": 100, "gear_cutting": 160, "polishing": 40},
    "min_production": 2,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.x = pyo.Var(
        model.P,
        domain=pyo.NonNegativeIntegers,
        bounds=(d["min_production"], None),
    )

    def profit_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(expr=profit_rule(model), sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(d["usage"][r][p] * m.x[p] for p in m.P) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "presses": ["four_color", "two_color"],
    "profit": {"four_color": 24000, "two_color": 10000},
    "rollers_used": {"four_color": 16, "two_color": 8},
    "rollers_available": 100,
    "gear_hours_used": {"four_color": 30, "two_color": 12},
    "gear_hours_available": 160,
    "polish_hours_used": {"four_color": 8, "two_color": 3},
    "polish_hours_available": 40,
    "min_units": {"four_color": 2, "two_color": 2},
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # --- Sets ---
    model.PRESSES = pyo.Set(initialize=d["presses"])

    # --- Variables ---
    model.production = pyo.Var(
        model.PRESSES,
        within=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    # --- Objective: maximise weekly profit ---
    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.PRESSES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # --- Constraints ---
    # Steel roller availability
    def rollers_rule(m):
        return sum(
            d["rollers_used"][p] * m.production[p] for p in m.PRESSES
        ) <= d["rollers_available"]

    model.rollers_limit = pyo.Constraint(rule=rollers_rule)

    # Gear cutting capacity
    def gear_rule(m):
        return sum(
            d["gear_hours_used"][p] * m.production[p] for p in m.PRESSES
        ) <= d["gear_hours_available"]

    model.gear_limit = pyo.Constraint(rule=gear_rule)

    # Polishing capacity
    def polish_rule(m):
        return sum(
            d["polish_hours_used"][p] * m.production[p] for p in m.PRESSES
        ) <= d["polish_hours_available"]

    model.polish_limit = pyo.Constraint(rule=polish_rule)

    # Minimum production of each press type
    def min_units_rule(m, p):
        return m.production[p] >= d["min_units"][p]

    model.min_units = pyo.Constraint(model.PRESSES, rule=min_units_rule)

    return model


if __name__ == "__main__":
    m = build_model()
    m.pprint()
